<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="description" content="Fast, friendly web hosting for small businesses, bloggers, and side projects. Simple plans, real human support.">
  <title>Hearthstone Hosting | Friendly Web Hosting</title>
  <style>
    :root {
      --bg: #fdfaf6;
      --surface: #ffffff;
      --text: #2b2a28;
      --muted: #6b6661;
      --accent: #d9622b;
      --accent-dark: #b34d1e;
      --border: #e8e1d8;
      --radius: 12px;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
    }

    a { color: var(--accent); text-decoration: none; }
    a:hover { text-decoration: underline; }

    .container {
      width: min(1100px, 92%);
      margin: 0 auto;
    }

    /* Header */
    header {
      position: sticky;
      top: 0;
      background: rgba(253, 250, 246, 0.95);
      backdrop-filter: blur(8px);
      border-bottom: 1px solid var(--border);
      z-index: 10;
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1rem 0;
    }

    .logo {
      font-weight: 700;
      font-size: 1.25rem;
      color: var(--text);
    }

    .logo span { color: var(--accent); }

    .nav-links {
      display: flex;
      gap: 1.5rem;
      list-style: none;
      align-items: center;
    }

    .nav-links a {
      color: var(--text);
      font-weight: 500;
    }

    .btn {
      display: inline-block;
      padding: 0.75rem 1.5rem;
      border-radius: 999px;
      font-weight: 600;
      transition: background 0.2s, transform 0.1s;
      border: 2px solid transparent;
      cursor: pointer;
      font-size: 1rem;
    }

    .btn:hover { text-decoration: none; transform: translateY(-1px); }

    .btn-primary {
      background: var(--accent);
      color: #fff;
    }
    .btn-primary:hover { background: var(--accent-dark); }

    .btn-outline {
      border-color: var(--accent);
      color: var(--accent);
      background: transparent;
    }
    .btn-outline:hover { background: var(--accent); color: #fff; }

    /* Hero */
    .hero {
      padding: 5rem 0 4rem;
      text-align: center;
    }

    .hero h1 {
      font-size: clamp(2.2rem, 5vw, 3.5rem);
      line-height: 1.15;
      margin-bottom: 1.25rem;
      letter-spacing: -0.02em;
    }

    .hero p {
      font-size: 1.2rem;
      color: var(--muted);
      max-width: 620px;
      margin: 0 auto 2rem;
    }

    .hero-actions {
      display: flex;
      gap: 1rem;
      justify-content: center;
      flex-wrap: wrap;
    }

    .hero-note {
      margin-top: 1.5rem;
      font-size: 0.9rem;
      color: var(--muted);
    }

    /* Sections */
    section { padding: 4rem 0; }

    section h2 {
      font-size: clamp(1.7rem, 3vw, 2.2rem);
      text-align: center;
      margin-bottom: 0.75rem;
    }

    .section-intro {
      text-align: center;
      color: var(--muted);
      max-width: 600px;
      margin: 0 auto 3rem;
    }

    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 1.5rem;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 2rem;
    }

    .card-icon {
      font-size: 2rem;
      margin-bottom: 0.75rem;
    }

    .card h3 {
      font-size: 1.2rem;
      margin-bottom: 0.5rem;
    }

    .card p {
      color: var(--muted);
      font-size: 0.95rem;
    }

    /* Pricing */
    .pricing { background: #f5efe6; }

    .plan {
      position: relative;
    }

    .plan.featured {
      border: 2px solid var(--accent);
    }

    .badge {
      position: absolute;
      top: -12px;
      left: 50%;
      transform: translateX(-50%);
      background: var(--accent);
      color: #fff;
      font-size: 0.75rem;
      font-weight: 700;
      padding: 0.25rem 0.75rem;
      border-radius: 999px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .plan h3 { font-size: 1.3rem; }

    .price {
      font-size: 2.5rem;
      font-weight: 700;
      margin: 0.75rem 0 0.25rem;
    }

    .price small {
      font-size: 1rem;
      font-weight: 400;
      color: var(--muted);
    }

    .plan ul {
      list-style: none;
      margin: 1.5rem 0;
    }

    .plan li {
      padding: 0.45rem 0;
      border-bottom: 1px solid var(--border);
      font-size: 0.95rem;
    }

    .plan li:last-child { border-bottom: none; }

    .plan .btn { width: 100%; text-align: center; }

    .plan-desc {
      color: var(--muted);
      font-size: 0.95rem;
    }

    /* Testimonials */
    .quote {
      font-size: 1.05rem;
      font-style: italic;
      margin-bottom: 1rem;
    }

    .quote-author {
      font-size: 0.9rem;
      color: var(--muted);
      font-style: normal;
      font-weight: 600;
    }

    /* CTA */
    .cta {
      background: var(--text);
      color: #fff;
      text-align: center;
      border-radius: 20px;
      padding: 4rem 2rem;
      margin: 0 auto 4rem;
    }

    .cta h2 { color: #fff; margin-bottom: 1rem; }
    .cta p { color: #d6d0c8; margin-bottom: 2rem; max-width: 520px; margin-left: auto; margin-right: auto; }
    .cta .btn-primary { font-size: 1.05rem; padding: 0.9rem 2rem; }

    /* Footer */
    footer {
      border-top: 1px solid var(--border);
      padding: 2.5rem 0;
      font-size: 0.9rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 1.5rem;
    }

    .footer-links {
      display: flex;
      gap: 1.25rem;
      list-style: none;
      flex-wrap: wrap;
    }

    .footer-links a { color: var(--muted); }

    /* Responsive */
    @media (max-width: 720px) {
      .nav-links li:not(:last-child) { display: none; }
      .hero { padding: 3.5rem 0 3rem; }
      section { padding: 3rem 0; }
    }
  </style>
</head>
<body>

  <header>
    <div class="container nav">
      <a href="#" class="logo">Hearth<span>stone</span></a>
      <ul class="nav-links">
        <li><a href="#features">Features</a></li>
        <li><a href="#pricing">Pricing</a></li>
        <li><a href="#support">Support</a></li>
        <li><a href="#" class="btn btn-outline">Log in</a></li>
      </ul>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero">
      <div class="container">
        <h1>Hosting that feels<br>like a good neighbor.</h1>
        <p>Fast servers, free SSL, daily backups, and real people who answer the phone. Hearthstone keeps your website online so you can focus on the work you love.</p>
        <div class="hero-actions">
          <a href="#pricing" class="btn btn-primary">See Plans</a>
          <a href="#features" class="btn btn-outline">Explore Features</a>
        </div>
        <p class="hero-note">30-day money-back guarantee. No contracts. Cancel anytime.</p>
      </div>
    </section>

    <!-- Features -->
    <section id="features">
      <div class="container">
        <h2>Everything you need, nothing you don't</h2>
        <p class="section-intro">We keep things simple so you can get online in minutes, not afternoons.</p>

        <div class="grid">
          <div class="card">
            <div class="card-icon">⚡</div>
            <h3>Fast by default</h3>
            <p>SSD storage, LiteSpeed caching, and servers in three regions keep your pages loading quickly for every visitor.</p>
          </div>
          <div class="card">
            <div class="card-icon">🔒</div>
            <h3>Free SSL included</h3>
            <p>Every site gets a free Let's Encrypt certificate, installed and renewed automatically. No setup required.</p>
          </div>
          <div class="card">
            <div class="card-icon">🛟</div>
            <h3>Daily backups</h3>
            <p>Your files and databases are backed up every night and kept for 30 days. Restore with one click from your dashboard.</p>
          </div>
          <div class="card">
            <div class="card-icon">🧰</div>
            <h3>One-click installs</h3>
            <p>WordPress, Ghost, Joomla, and more install in under a minute. Updates are handled for you, if you want them.</p>
          </div>
          <div class="card">
            <div class="card-icon">📧</div>
            <h3>Email that works</h3>
            <p>Professional email on your own domain, with spam filtering and webmail included on every plan.</p>
          </div>
          <div class="card">
            <div class="card-icon">🌱</div>
            <h3>Green energy</h3>
            <p>Our data centers run on 100% renewable electricity, and we offset the rest of our footprint every year.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Pricing -->
    <section id="pricing" class="pricing">
      <div class="container">
        <h2>Simple, honest pricing</h2>
        <p class="section-intro">One price, no surprise fees at renewal. Upgrade or downgrade whenever you like.</p>

        <div class="grid">
          <div class="card plan">
            <h3>Starter</h3>
            <p class="plan-desc">For a single personal site or portfolio.</p>
            <div class="price">$4<small>/mo</small></div>
            <ul>
              <li>1 website</li>
              <li>10 GB SSD storage</li>
              <li>Free SSL</li>
              <li>Daily backups (7 days)</li>
              <li>Email support</li>
            </ul>
            <a href="#" class="btn btn-outline">Choose Starter</a>
          </div>

          <div class="card plan featured">
            <span class="badge">Most popular</span>
            <h3>Growth</h3>
            <p class="plan-desc">For small businesses and busy blogs.</p>
            <div class="price">$9<small>/mo</small></div>
            <ul>
              <li>5 websites</li>
              <li>50 GB SSD storage</li>
              <li>Free SSL and free domain for year one</li>
              <li>Daily backups (30 days)</li>
              <li>Professional email included</li>
              <li>Priority support</li>
            </ul>
            <a href="#" class="btn btn-primary">Choose Growth</a>
          </div>

          <div class="card plan">
            <h3>Studio</h3>
            <p class="plan-desc">For agencies and developers with lots of clients.</p>
            <div class="price">$19<small>/mo</small></div>
            <ul>
              <li>Unlimited websites</li>
              <li>200 GB SSD storage</li>
              <li>Free SSL and white-label panel</li>
              <li>Hourly backups (30 days)</li>
              <li>Staging environments</li>
              <li>Phone and chat support</li>
            </ul>
            <a href="#" class="btn btn-outline">Choose Studio</a>
          </div>
        </div>
      </div>
    </section>

    <!-- Testimonials -->
    <section>
      <div class="container">
        <h2>Loved by our customers</h2>
        <p class="section-intro">Small teams and solo creators trust us with their sites every day.</p>

        <div class="grid">
          <div class="card">
            <p class="quote">"I moved my bakery's site over on a Sunday and had questions answered before I finished my coffee. Support is actually human."</p>
            <p class="quote-author">Maria Okafor, Sweet Rise Bakery</p>
          </div>
          <div class="card">
            <p class="quote">"Three client sites, one dashboard, and backups I've actually needed twice. It just works."</p>
            <p class="quote-author">Tom Halvorsen, Freelance Designer</p>
          </div>
          <div class="card">
            <p class="quote">"Our site loads faster than it did on the expensive host we left. The price difference was a bonus."</p>
            <p class="quote-author">Priya Raman, Raman Tutoring</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Support -->
    <section id="support">
